return {["scripts/items/hydra_tights.lua"]={["Path"]="scripts/items/hydra_tights.lua",["SHA256"]="b857237cbd454c65857f69a238ac20cc6e07eb4b19521cbcb2ba02b879301018",["Text"]="-----------------------------------\n-- ID: 15596\n-- Item: Hydra Tights\n-- Item Effect: Haste +10% (Magic)\n-- Duration: 3 Minutes\n-- Stacks with Haste (spell)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.HYDRA_TIGHTS) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HYDRA_TIGHTS)\n        if effect then\n            effect:resetStartTime()\n            effect:setIcon(xi.effect.HASTE)\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, icon = xi.effect.HASTE, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.HYDRA_TIGHTS, flag = xi.effectFlag.NO_LOSS_MESSAGE })\n        end\n\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.HASTE)\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HASTE_MAGIC, 1000)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.HYDRA_TIGHTS)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:messageBasic(xi.msg.basic.STATUS_WEARS_OFF, xi.effect.HASTE)\nend\n\nreturn itemObject\n"},["scripts/items/hydro_axe.lua"]={["Path"]="scripts/items/hydro_axe.lua",["SHA256"]="6939f5391ae79046eae76a26df2948de79c6dfc5e1fc62ca7d428b9fe16532dc",["Text"]="-----------------------------------\n-- ID: 18200\n-- Item: Hydro Axe\n-- Additional effect: water damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WATER, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 30,\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WATER,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/hydro_axe_+1.lua"]={["Path"]="scripts/items/hydro_axe_+1.lua",["SHA256"]="13ae58116bc0cb145fdb8345925d4fb4b8b5f3c65207d5239e3dd723782e397c",["Text"]="-----------------------------------\n-- ID: 18201\n-- Item: Hydro Axe +1\n-- Additional effect: water damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WATER, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 30,\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WATER,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/hydro_baghnakhs.lua"]={["Path"]="scripts/items/hydro_baghnakhs.lua",["SHA256"]="acdba2b3cbdff6b1b4a987de7819