e,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/hydro_patas_+1.lua"]={["Path"]="scripts/items/hydro_patas_+1.lua",["SHA256"]="95e5f7cbf74e0b5ba8e57735a3550e7b7716ef780327f0f29dc93b1914998f0d",["Text"]="-----------------------------------\n-- ID: 17517\n-- Item: Hydro Patas +1\n-- Additional effect: water damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WATER, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 10,\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WATER,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/hydrohelix_schema.lua"]={["Path"]="scripts/items/hydrohelix_schema.lua",["SHA256"]="f944d43ab0c725c846663ef2b02e925b1a2ecb6e380a0aabb46ad5f81a2bf4e2",["Text"]="-----------------------------------\n-- ID: 6042\n-- Hydrohelix Schema\n-- Teaches the black magic Hydrohelix\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.HYDROHELIX)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.HYDROHELIX)\nend\n\nreturn itemObject\n"},["scripts/items/hyper_ether.lua"]={["Path"]="scripts/items/hyper_ether.lua",["SHA256"]="28bef3b7794cc29428c241052defbea4262ca106385b87dc9664cd0674420393",["Text"]="-----------------------------------\n-- ID: 5255\n-- Item: Hyper-Ether\n-- Item Effect: Restores 125 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(125 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 300, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/hyper_potion.lua"]={["Path"]="scripts/items/hyper_potion.lua",["SHA256"]="5b745fbe20d9aa6910499c73af9a27eb79b2df2c3fa701eec9ad2343914c3fa8",["Text"]="-----------------------------------\n-- ID: 5254\n-- Item: Hyper-Potion\n-- Item Effect: Restores 250 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(250 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 300, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/icarus_wing.lua"]={["Path"]="scripts/items/icarus_wing.lua",["SHA256"]="85faab53e2e707f7a2a0598d2f6c59b8769d1c8205bd010599aa436bad29cbc1",["Text"]="-----------------------------------\n-- ID: 4213\n-- Icarus Wing\n-- Increases TP of the user by 1000\n-- Modified by Store TP. https://wiki.ffo.jp/html/3809.html\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local storeTPModifier = 1 + (target:getMod(xi.mod.STORETP) + target:getMerit(xi.merit.STORE_TP_EFFECT)) / 100\n\n    target:addTP(math.floor(1000 * storeTPModifier))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 7200, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/ice_arrow.lua"]={["Path"]="scripts/items/ice_arrow.lua",["SHA256"]="9b39057b537c1013250def90482a8723d4ceca1a9dfca694bdbc66314305428a",["Text"]="-----------------------------------\n-- ID: 17323\n-- Item: Ice Arrow\n-- Additional effect: Ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    -- Unconfirmed power.\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = math.random(7, 10),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.ICE,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/ice_card_case.lua"]={["Path"]="scripts/items/ice_card_case.lua",["SHA256"]="0255d2a1896b82e325a086d0efa3dfd9c738bd2325ff22d08935136a11a30a63",["Text"]="-----------------------------------\n-- ID: 5403\n-- Ice Card Case\n-- When used, you will obtain one stack of Ice Cards\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ICE_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/ice_cluster.lua"]={["Path"]="scripts/items/ice_cluster.lua",["SHA256"]="42270aaf38a3d17e3ecab680098847e8ae12da730efd4ceccee4bc0514305143",["Text"]="-----------------------------------\n-- ID: 4105\n-- Ice Cluster\n-- Turn into a stack of ice crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ICE_CRYSTAL, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/ice_lance.lua"]={["Path"]="scripts/items/ice_lance.lua",["SHA256"]="8c4bc46400982cd3061ba56b25961409f9047126b806792c338c47bb77d1b65d",["Text"]="-----------------------------------\n-- ID: 16861\n-- Item: Ice Lance\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 8 + utils.clamp(dStat * 7 / 54, 0, 7), -- 7% over dINT54\n        basePower      = math.randomInt(15, 20),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/ice_lance_+1.lua"]={["Path"]="scripts/items/ice_lance_+1.lua",["SHA256"]="167e9a899f1b3dc2d9e39bd75f3113405ed8ab6d7f87a011369f5ae100e6f09a",["Text"]="-----------------------------------\n-- ID: 16895\n-- Item: Ice Lance +1\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 8 + utils.clamp(dStat * 7 / 54, 0, 7), -- 7% over dINT54\n        basePower      = math.randomInt(15, 20),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/ice_spirit_pact.lua"]={["Path"]="scripts/items/ice_spirit_pact.lua",["SHA256"]="ffaead4ea1d69a760dafb97a87f7ca1fa6023c22202b22b3cf0371d83ce49bd0",["Text"]="-----------------------------------\n-- ID: 4897\n-- Ice Spirit Pact\n-- Teaches the summoning magic ice Spirit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.ICE_SPIRIT)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.ICE_SPIRIT)\nend\n\nreturn itemObject\n"},["scripts/items/ice_staff.lua"]={["Path"]="scripts/items/ice_staff.lua",["SHA256"]="a0083f4381093792f87956b379243f9fe4b7694df5896b342574efc72060f8ec",["Text"]="-----------------------------------\n-- ID: 17547\n-- Item: Ice Staff\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 15, -- guessed\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/ice_trousers.lua"]={["Path"]="scripts/items/ice_trousers.lua",["SHA256"]="205133bd935791a886561728b9c987f31548d485c97128b42823d636ba56031c",["Text"]="-----------------------------------\n-- ID: 15651\n-- Item: Ice Trousers\n-- Item Effect: Ice Spikes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.ICE_SPIKES, { power = 7, duration = 180, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/icefish.lua"]={["Path"]="scripts/items/icefish.lua",["SHA256"]="a93789b874dea9c576c7f263cf7e8f9ac586150e8e4cc26d79493dbcc5bb8f51",["Text"]="-----------------------------------\n-- ID: 4470\n-- Item: icefish\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ichinintousen_koma.lua"]={["Path"]="scripts/items/ichinintousen_koma.lua",["SHA256"]="4f7a474f4af14cf3ea22eff62e16346c2d9637b6d7cdbec0cd09077efff2b1c1",["Text"]="-----------------------------------\n-- ID: 5532\n-- Ichinintousen Koma\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/icicle_sword.lua"]={["Path"]="scripts/items/icicle_sword.lua",["SHA256"]="23673ac83a1d45d2aa7f9832086e461bd0bed203fcb0630bc7e10c407394cac8",["Text"]="-----------------------------------\n-- ID: 16937\n-- Item: Icicle Sword\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 5 + utils.clamp(dStat * 5 / 54, 0, 5), -- linear interpolation\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/ifrits_blade.lua"]={["Path"]="scripts/items/ifrits_blade.lua",["SHA256"]="f0dc046daab942df2a8b1bfd8dda33c583366f28ac6c6b750f4cc4351fd17752",["Text"]="-----------------------------------\n-- ID: 17665\n-- Item: Ifrit's Blade\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local chance = 3 -- TODO: check scaling on non-firesday\n\n    if VanadielDayOfTheWeek() == xi.day.FIRESDAY then\n        chance = xi.additionalEffect.linearProcRate(dStat, 140, 15, 50) -- Numbers are smoothed out a bit. Scale from 15% at dINT 0 to 50% at +140 DINT\n    end\n\n    local pTable =\n    {\n        chance         = chance,\n        basePower      = math.randomInt(18, 25),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/iga_shuriken_pouch.lua"]={["Path"]="scripts/items/iga_shuriken_pouch.lua",["SHA256"]="18a5c282cf9eb45328c47e70577dea5aa8aac972a176157a4db2557325d41e9c",["Text"]="-----------------------------------\n-- ID: 6303\n-- Item: Iga Sh. Pouch\n-- When used, you will obtain one stack of Iga Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.IGA_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/imperial_chair_set.lua"]={["Path"]="scripts/items/imperial_chair_set.lua",["SHA256"]="6ca0ee32eb0ea549b577b3bfc61a498b75a58773af346228e2afb233e7133ea6",["Text"]="-----------------------------------\n-- ID: 6377\n-- Item: Imperial Chair\n-- Item Effect: Grant Imperial chair key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.IMPERIAL_CHAIR\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, 6377, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/imperial_omelette.lua"]={["Path"]="scripts/items/imperial_omelette.lua",["SHA256"]="bc0863eaa8ead4e451f5dad846efa2f062aebcd44ab095fd628b572ee5c7eea1",["Text"]="-----------------------------------\n-- ID: 4331\n-- Item: imperial_omelette\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Non Elvaan Stats\n-- Strength 5\n-- Dexterity 2\n-- Intelligence -3\n-- Mind 4\n-- Attack % 22\n-- Attack Cap 70\n-- Ranged ATT % 22\n-- Ranged ATT Cap 70\n-----------------------------------\n-- Elvaan Stats\n-- Strength 7\n-- Health 30\n-- Magic 30\n-- Intelligence -1\n-- Mind 6\n-- Charisma 5\n-- Attack % 20 (cap 80)\n-- Ranged ATT % 20 (cap 80)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local targetRace = target:getRace()\n\n    if\n        targetRace == xi.race.ELVAAN_M or\n        targetRace == xi.race.ELVAAN_F\n    then\n        effect:addMod(xi.mod.STR, 5)\n        effect:addMod(xi.mod.DEX, 2)\n        effect:addMod(xi.mod.INT, -3)\n        effect:addMod(xi.mod.MND, 4)\n        effect:addMod(xi.mod.FOOD_ATTP, 22)\n        effect:addMod(xi.mod.FOOD_ATT_CAP, 70)\n        effect:addMod(xi.mod.FOOD_RATTP, 22)\n        effect:addMod(xi.mod.FOOD_RATT_CAP, 70)\n    else\n        effect:addMod(xi.mod.FOOD_HP, 30)\n        effect:addMod(xi.mod.FOOD_MP, 30)\n        effect:addMod(xi.mod.STR, 7)\n        effect:addMod(xi.mod.DEX, 3)\n        effect:addMod(xi.mod.INT, -1)\n        effect:addMod(xi.mod.MND, 6)\n        effect:addMod(xi.mod.CHR, 5)\n        effect:addMod(xi.mod.FOOD_ATTP, 20)\n        effect:addMod(xi.mod.FOOD_ATT_CAP, 80)\n        effect:addMod(xi.mod.FOOD_RATTP, 20)\n        effect:addMod(xi.mod.FOOD_RATT_CAP, 80)\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/incus_cell.lua"]={["Path"]="scripts/items/incus_cell.lua",["SHA256"]="af7899942ca176a290fe3d80fe7687d83424b93edd5497e2e722da21f2a28b0e",["Text"]="-----------------------------------\n-- Incus Cell\n-- ID 5365\n-- Unlocks weapons and shields\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.ENCUMBRANCE_I, 0x0003)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.ENCUMBRANCE_I, 0x0003, 0)\nend\n\nreturn itemObject\n"},["scripts/items/indra_katars.lua"]={["Path"]="scripts/items/indra_katars.lua",["SHA256"]="415db3b055a7df25d7e80e423440b9f3abfbb9201aad46a6eb71423796ea3ec4",["Text"]="-----------------------------------\n-- ID: 17511\n-- Item: Indra Katars\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(8, 10),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/inferno_axe.lua"]={["Path"]="scripts/items/inferno_axe.lua",["SHA256"]="dd712814a30a65943eb49e784bd208f91fd7ab90c303f94cbe03debe843a0c30",["Text"]="-----------------------------------\n-- ID: 16709\n-- Item: Inferno Axe\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/intelligence_potion.lua"]={["Path"]="scripts/items/intelligence_potion.lua",["SHA256"]="d59040d93905890379c257ab941ad4b5207af61471e7edba814faf7f1b5c725c",["Text"]="-----------------------------------\n--  ID: 4207\n--  Item: Intelligence Potion\n--  Intelligence 7\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.INT_BOOST, { power = 7, duration = 180, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/investigative_report.lua"]={["Path"]="scripts/items/investigative_report.lua",["SHA256"]="f6619a693b2d0ecfee9250e12b1e54e1932bbb691bf6b0765fe4dbbe0017ea30",["Text"]="-----------------------------------\n-- ID: 6169\n-- Item: Inv. Report\n-- A collection of observations made by Rainemard on a particular exploration.\n-- It goes into such detail on so much minutiae that many admit to never finishing it.\n-- Adventurers note that reading it increases one's enfeebling magic skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.ENFEEBLING_MAGIC)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.ENFEEBLING_MAGIC)\nend\n\nreturn itemObject\n"},["scripts/items/invisible_mantle.lua"]={["Path"]="scripts/items/invisible_mantle.lua",["SHA256"]="fbc4bb8b9aca4a6c0463809d92d7b47b51369fd1afe670fe4a356ed8f384b04e",["Text"]="-----------------------------------\n-- ID: 13685\n-- Item: Invisible Mantle\n-- Item Effect: gives invisible\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.INVISIBLE_MANTLE) then\n        if target:hasStatusEffect(xi.effect.INVISIBLE) then\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        else\n            target:addStatusEffect(xi.effect.INVISIBLE, { duration = math.floor(180 * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user, tick = 10, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.INVISIBLE_MANTLE })\n        end\n    end\nend\n\nreturn itemObject\n"},["scripts/items/ionohelix_schema.lua"]={["Path"]="scripts/items/ionohelix_schema.lua",["SHA256"]="d6839cab219b2b27be1f722c7f1e9eb8f89c8743280d3ed07855cb189fa4a2cb",["Text"]="-----------------------------------\n-- ID: 6043\n-- Ionohelix Schema\n-- Teaches the black magic Ionohelix\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.IONOHELIX)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.IONOHELIX)\nend\n\nreturn itemObject\n"},["scripts/items/irmik_helvasi.lua"]={["Path"]="scripts/items/irmik_helvasi.lua",["SHA256"]="393f5ab7b14cbd2e88f55122cdaae71349201bd8ba1d2650ec9914ebea455e41",["Text"]="-----------------------------------\n-- ID: 5572\n-- Item: irmik_helvasi\n-- Food Effect: 3 hours, All Races\n-----------------------------------\n-- HP +10% (cap 75)\n-- MP +3% (cap 13)\n-- INT +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 75)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 13)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/irmik_helvasi_+1.lua"]={["Path"]="scripts/items/irmik_helvasi_+1.lua",["SHA256"]="e38f6dfd0ba4e3078ce36ddbf5617dc6432753d4a38facc2a7c2893519c643d6",["Text"]="-----------------------------------\n-- ID: 5573\n-- Item: irmik_helvasi_+1\n-- Food Effect: 4 hours, All Races\n-----------------------------------\n-- HP +10% (cap 100)\n-- MP +3% (cap 15)\n-- INT +2\n-- hHP +1\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 100)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 15)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/iron_bullet_pouch.lua"]={["Path"]="scripts/items/iron_bullet_pouch.lua",["SHA256"]="dc6dfeb622d11099fffc6de0905cdedab879c1d1952af3fa2607c908afa041d2",["Text"]="-----------------------------------\n-- ID: 5353\n-- Iron Bullet Pouch\n-- When used, you will obtain one stack of Iron Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.IRON_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/iron_musketeers_quiver.lua"]={["Path"]="scripts/items/iron_musketeers_quiver.lua",["SHA256"]="94e3c86f9c22b97053eef32018d541909352d1eb3082b908a60f8beb86f19d78",["Text"]="-----------------------------------\n-- ID: 15957\n-- Iron Musketeer's Quiver\n-- When used, you will obtain one Iron Musketeer's Bolt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.IRON_MUSKETEERS_BOLT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/iron_quiver.lua"]={["Path"]="scripts/items/iron_quiver.lua",["SHA256"]="f6b11024c6d0c2b557f1248d7b9b617fed7f578ee9a1cb0d70449b65118289af",["Text"]="-----------------------------------\n-- ID: 4225\n-- Iron Quiver\n-- When used, you will obtain one stack of Iron Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.IRON_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/istakoz.lua"]={["Path"]="scripts/items/istakoz.lua",["SHA256"]="f43bad858a1baa7b40d7e785f4a2ff9aed4face36b51d8e8b418a0eebd2aa7fe",["Text"]="-----------------------------------\n-- ID: 5453\n-- Item: Istakoz\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 3\n-- Defense +16% (cap 50)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_DEFP, 16)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/istiridye.lua"]={["Path"]="scripts/items/istiridye.lua",["SHA256"]="3379cb5db650e8ec7ec7bc0b84e3a264d4a51e5ed5e0a5acc7771e35575f0873",["Text"]="-----------------------------------\n-- ID: 5456\n-- Item: Istiridye\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 4\n-- Defense +17.07%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.DEFP, 17.07)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/jack-o-lantern.lua"]={["Path"]="scripts/items/jack-o-lantern.lua",["SHA256"]="b095521c90ea6110f6786b808b03b3b96dc9f34bf6bdecfaa383d1f4bc241801",["Text"]="-----------------------------------\n-- ID: 4488\n-- Item: jack-o-lantern\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Charisma -10\n-- Accuracy 10\n-- Ranged Acc 10\n-- Evasion 10\n-- Arcana Killer 4\n-- Dark Res 25\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.CHR, -10)\n    effect:addMod(xi.mod.ACC, 10)\n    effect:addMod(xi.mod.RACC, 10)\n    effect:addMod(xi.mod.EVA, 10)\n    effect:addMod(xi.mod.ARCANA_KILLER, 4)\n    effect:addMod(xi.mod.DARK_MEVA, 25)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/jack-o-pie.lua"]={["Path"]="scripts/items/jack-o-pie.lua",["SHA256"]="99fe218d6ca171c0b3483938e22424a519fc0d3c711279e855a22fab3e09ba33",["Text"]="-----------------------------------\n-- ID: 5644\n-- Item: jack-o-pie\n-- Food Effect: 1hour, All Races\n-----------------------------------\n-- MP 45\n-- CHR -1\n-- Intelligence 4\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 45)\n    effect:addMod(xi.mod.CHR, -1)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/jacknife.lua"]={["Path"]="scripts/items/jacknife.lua",["SHA256"]="e2505f290b5eb8a9dc41b900aa721e7f50a1e3b4e852bee1b1dcb59ec2d612f7",["Text"]="-----------------------------------\n-- ID: 5123\n-- Item: Jacknife\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 4\n-- Defence 16% Cap 50\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FOOD_DEFP, 16)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/janizary_earring.lua"]={["Path"]="scripts/items/janizary_earring.lua",["SHA256"]="cb9f3429c93d1b1a8b8bbf990cdd7765358fcb5c1529c48a8d845ad671f67d6c",["Text"]="-----------------------------------\n-- ID: 14785\n-- Item: Janizary Earring\n-- Item Effect: Defence +32\n-- Duration 3 Minutes\n-- https://wiki.ffo.jp/html/10065.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.JANIZARY_EARRING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.JANIZARY_EARRING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.JANIZARY_EARRING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEF, 32)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.JANIZARY_EARRING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/jar_of_ground_wasabi.lua"]={["Path"]="scripts/items/jar_of_ground_wasabi.lua",["SHA256"]="c1154d06ccc6f856d7831dcc12a819a14eee09c00a0b5a7723a80661481ee15d",["Text"]="-----------------------------------\n-- ID: 5164\n-- Item: jar_of_ground_wasabi\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Strength -1\n-- Dexterity -1\n-- Agility -1\n-- Vitality -1\n-- Intelligence -1\n-- Mind -1\n-- Charisma -1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -1)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.CHR, -1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/jar_of_marinara_sauce.lua"]={["Path"]="scripts/items/jar_of_marinara_sauce.lua",["SHA256"]="81a1b110493faf9dd87709162a5bfecc4b6ce71fdc18abd7cedd2039a674625b",["Text"]="-----------------------------------\n-- ID: 5747\n-- Item: Jar of Marinara Sauce\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Mind 2\n-- Intelligence 1\n-- HP recovered while healing +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MND, 2)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/jar_of_remedy_ointment.lua"]={["Path"]="scripts/items/jar_of_remedy_ointment.lua",["SHA256"]="bfd0b48f41227219dd72a9599b2aabf5a0a393afdd1f0ec1d37ef61f3cc5f5a8",["Text"]="-----------------------------------\n-- ID: 5356\n-- Item: Remedy Ointment\n-- Item Effect: This potion remedies status ailments.\n-- Works on paralysis, silence, blindness, poison, and disease.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    if\n        target:hasStatusEffect(xi.effect.SILENCE) or\n        target:hasStatusEffect(xi.effect.BLINDNESS) or\n        target:hasStatusEffect(xi.effect.POISON) or\n        target:hasStatusEffect(xi.effect.PARALYSIS) or\n        target:hasStatusEffect(xi.effect.DISEASE)\n    then\n        local effectRemoved = 0\n        while effectRemoved == 0 do\n            local num = math.randomInt(1, 5)\n            if num == 1 and target:hasStatusEffect(xi.effect.SILENCE) then\n                effectRemoved = effectRemoved + 1\n                target:delStatusEffect(xi.effect.SILENCE)\n\n            elseif num == 2 and target:hasStatusEffect(xi.effect.BLINDNESS) then\n                effectRemoved = effectRemoved + 1\n                target:delStatusEffect(xi.effect.BLINDNESS)\n\n            elseif num == 3 and target:hasStatusEffect(xi.effect.POISON) then\n                effectRemoved = effectRemoved + 1\n                target:delStatusEffect(xi.effect.POISON)\n\n            elseif num == 4 and target:hasStatusEffect(xi.effect.PARALYSIS) then\n                effectRemoved = effectRemoved + 1\n                target:delStatusEffect(xi.effect.PARALYSIS)\n\n            elseif num == 5 and target:hasStatusEffect(xi.effect.DISEASE) then\n                effectRemoved = effectRemoved + 1\n                target:delStatusEffect(xi.effect.DISEASE)\n            end\n        end\n    end\nend\n\nreturn itemObject\n"},["scripts/items/jesters_hat.lua"]={["Path"]="scripts/items/jesters_hat.lua",["SHA256"]="d7cf595ecc7b9c64a8b63df8fe818d2f6d575f9a4711914040640e3d23142d8e",["Text"]="-----------------------------------\n-- ID: 11788\n-- Item: Jester's Hat\n-- Item Effect: Casts Cure II\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local hpHeal = 90\n    local dif = target:getMaxHP() - target:getHP()\n    if hpHeal > dif then\n        hpHeal = dif\n    end\n\n    target:addHP(hpHeal)\n    target:updateEnmityFromCure(target, hpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, hpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/jet_sickle.lua"]={["Path"]="scripts/items/jet_sickle.lua",["SHA256"]="f17d0cb4cdbbd55b58c2b28cf1bc75fa2d993c2fc7c20940de552d57705031f9",["Text"]="-----------------------------------\n-- ID: 18945\n-- Item: Jet Sickle\n-- Item Effect: TP +100\n-- Duration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/jolt_axe.lua"]={["Path"]="scripts/items/jolt_axe.lua",["SHA256"]="c86170cdbb49dc239d648f3e1c7f1d371a372eeff5b3e228fd9861e2c730ef6b",["Text"]="-----------------------------------\n-- ID: 17954\n-- Item: jolt_axe\n-- Item Effect: Attack +3\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ATTACK_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.JOLT_AXE) ~= nil then\n        target:delStatusEffect(xi.effect.ATTACK_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.JOLT_AXE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.JOLT_AXE) then\n        target:addStatusEffect(xi.effect.ATTACK_BOOST, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.JOLT_AXE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ATT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/joyous_serinette.lua"]={["Path"]="scripts/items/joyous_serinette.lua",["SHA256"]="691bf229d4f8121816d45d81832a3cc6b7500fe9ab66b97166d3eafb585b6ebb",["Text"]="-----------------------------------\n-- ID: 5425\n-- Item: Joyous Serinette\n-- Item Effect: Change Music\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local alliance = target:getAlliance()\n    for i, member in pairs(alliance) do\n        if member:getZoneID() == target:getZoneID() then\n            member:changeMusic(xi.musicSlot.ZONE_DAY, 214)   -- Eternal Oath\n            member:changeMusic(xi.musicSlot.ZONE_NIGHT, 214) -- Eternal Oath\n        end\n    end\nend\n\nreturn itemObject\n"},["scripts/items/jug_of_marys_milk.lua"]={["Path"]="scripts/items/jug_of_marys_milk.lua",["SHA256"]="ab86be54e6e684e2b178e2677f0fc97421f6cb3665b5355cf420e448657fd2a5",["Text"]="-----------------------------------\n-- ID: 4527\n-- Item: Jug of marys milk\n-- Item Effect: This potion induces sleep.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if\n        not target:hasStatusEffect(xi.effect.SLEEP_I) and\n        not target:hasStatusEffect(xi.effect.SLEEP_II) and\n        not target:hasStatusEffect(xi.effect.LULLABY)\n    then\n        target:addStatusEffect(xi.effect.SLEEP_I, { power = 1, duration = 60, origin = user })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/jug_of_miracle_milk.lua"]={["Path"]="scripts/items/jug_of_miracle_milk.lua",["SHA256"]="2f505efc88a09ee166c346e53d41eda31e2a6fcab6d63d7ca5f13fb6e7c7e242",["Text"]="-----------------------------------\n-- ID: 5733\n-- Jug of Miracle Milk\n-- Enchantment: 60Min, Costume - Chigoe (red)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 1747, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/jug_of_selbina_milk.lua"]={["Path"]="scripts/items/jug_of_selbina_milk.lua",["SHA256"]="d2f38cce8e0cf430655e7fef5ef59beac653a52a8e1e369fb4054e832bda3c7b",["Text"]="-----------------------------------\n-- ID: 4378\n-- Item: Jug of Selbina Milk\n-- Item Effect: regen: 1 HP/tick x 120sec, x 150sec w/ dream robe +1\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect   = target:getStatusEffect(xi.effect.REGEN)\n    local bodyEquipped  = target:getEquipID(xi.slot.BODY)\n    local regenDuration = bodyEquipped == xi.item.DREAM_ROBE_P1 and 150 or 120\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 1, duration = regenDuration, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/jug_of_soy_milk.lua"]={["Path"]="scripts/items/jug_of_soy_milk.lua",["SHA256"]="f8a9430af75891bb516ee01d2c2719d2360d90877f4a6d7103672e042ad86641",["Text"]="-----------------------------------\n-- ID: 5232\n-- Item: Soy Milk\n-- Item Effect: Restores 40 HP over 120 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 1, duration = 120, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/jug_of_uleguerand_milk.lua"]={["Path"]="scripts/items/jug_of_uleguerand_milk.lua",["SHA256"]="8abf11aea39ffbab8341bd7751fa300622dc88d489adf568b4868f647eaa1d8e",["Text"]="-----------------------------------\n-- ID: 5703\n-- Item: Uleguerand Milk\n-- Item Effect: Restores 80 HP over 120 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 2, duration = 120, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/juglan_jumble.lua"]={["Path"]="scripts/items/juglan_jumble.lua",["SHA256"]="231d5c2430cbf48d94434c989cc4faac8e0c218d00cceb09ba8b76b3138f610d",["Text"]="-----------------------------------\n-- ID: 5923\n-- Item: Juglan Jumble\n-- Food Effect: 5 Min, All Races\n-----------------------------------\n-- HP Healing 5\n-- MP Healing 8\n-- Bird Killer 12\n-- Resist Paralyze 12\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 5)\n    effect:addMod(xi.mod.MPHEAL, 8)\n    effect:addMod(xi.mod.BIRD_KILLER, 12)\n    effect:addMod(xi.mod.PARALYZERES, 12)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/juji_shuriken_pouch.lua"]={["Path"]="scripts/items/juji_shuriken_pouch.lua",["SHA256"]="2e87ba9b2be918a2ba5947912fa97afbfda1cd8bad49feb561016fe1421ac15a",["Text"]="-----------------------------------\n-- ID: 6297\n-- Item: Juji Shr. Pouch\n-- When used, you will obtain one stack of Juji Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.JUJI_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"}};
